const uploadSourceMaps = async (buildId) => {
    const sourceMapFiles = await glob('dist/**/*.map');

    for (const file of sourceMapFiles) {
        await uploadToDebugServer({
            buildId,
            file,
            version: process.env.APP_VERSION
        });
    }
};

